    const json = pm.response.json();
    const college = json.colleges.find(c => c.collegeName === "QA Mentor Test College");
    pm.expect(college).to.not.be.undefined;
    const majorNames = college.majors.map(m => m.majorName);
    pm.expect(majorNames).to.include("QA Mentor Test Major");
