    const courseId = pm.variables.get("courseId");

    pm.test("QA-07 | Courses array exists", function () {
        pm.expect(data.courses).to.be.an("array");
    });

    pm.test("QA-07 | QA101 course exists", function () {
        const course = data.courses.find(
            c => c.courseId === courseId
        );

        pm.expect(course).to.not.be.undefined;
        pm.expect(course.courseCode).to.eql("QA101");
    });

    pm.test("QA-07 | Course is not enrolled", function () {
        const course = data.courses.find(
            c => c.courseId === courseId
        );

        pm.expect(course).to.not.be.undefined;
        pm.expect(course.isEnrolled).to.eql(false);
    });
}

